const response = $json.body ?? $json;
if ($json.headers?.warning || response.is_partial === true || response.is_running === true || response.error) {
  throw new Error('ES|QL returned warnings, errors, or incomplete results; retaining the previous snapshot.');
}
if (!Array.isArray(response.columns) || !Array.isArray(response.values) || response.values.length !== 1) {
  throw new Error('Expected exactly one ES|QL result row.');
}
const row = response.values[0];
const results = {};
for (const name of ['managed', 'unmanaged', 'coverage_pct']) {
  const matches = response.columns.map((column, index) => column.name === name ? index : -1).filter(index => index >= 0);
  if (matches.length !== 1 || !Array.isArray(row) || row.length !== response.columns.length) throw new Error('Unexpected ES|QL columns.');
  results[name] = row[matches[0]];
}
const { managed, unmanaged, coverage_pct } = results;
if (!Number.isSafeInteger(managed) || managed < 0 || !Number.isSafeInteger(unmanaged) || unmanaged < 0 || !Number.isSafeInteger(managed + unmanaged)) {
  throw new Error('Invalid asset counts.');
}
const expected = managed + unmanaged === 0 ? null : Math.round(managed * 1000 / (managed + unmanaged)) / 10;
if (expected === null ? coverage_pct !== null : typeof coverage_pct !== 'number' || !Number.isFinite(coverage_pct) || Math.abs(coverage_pct - expected) > 0.000001) {
  throw new Error('Coverage percentage does not match the counts.');
}
return [{ json: { queryId: 'asset-coverage', collectedAt: $('Start query').first().json.collectedAt, results } }];
